function parseHeader(raw) {
  const parts = raw.split(':');
  const key = parts[0].trim();
  const value = parts.slice(1).join(':').trim();
  return { key, value };
}

function parseQuery(raw) {
  return raw.split('&').map(p => p.split('='));
}

