package ratelimit

import 'time'

type Bucket struct {
	tokens   float64
	last     time.Time
	rate     float64
	capacity float64
}

func (b *Bucket) Allow(now time.Time) bool {
	b.tokens += now.Sub(b.last).Seconds() * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

